#!/usr/bin/env bash
# Create the two logins inside the running backend task, via ECS Exec.
# Called by scripts/aws-up.sh after every apply; safe to run again. Existing
# users get their password set to the SSM value (--update), so the admin
# password is always what /roster/ADMIN_PASSWORD says.
#
#   admin    - web UI login. Password generated by Terraform, in SSM at
#              /roster/ADMIN_PASSWORD.
#   svc-mcp  - the MCP server's service account, /roster/ROSTER_SERVICE_PASSWORD.
#
# Needs the session-manager-plugin installed next to the aws CLI.
set -euo pipefail

CLUSTER=roster

param() {
  aws ssm get-parameter --name "/roster/$1" --with-decryption \
    --query Parameter.Value --output text
}

echo "==> waiting for the backend service to be stable"
aws ecs wait services-stable --cluster "$CLUSTER" --services backend

TASK=$(aws ecs list-tasks --cluster "$CLUSTER" --service-name backend \
  --desired-status RUNNING --query 'taskArns[0]' --output text)
if [ -z "$TASK" ] || [ "$TASK" = "None" ]; then
  echo "no running backend task in cluster $CLUSTER" >&2
  exit 1
fi

# ECS Exec does not relay the command's exit code, so the output is the
# only signal.
create_user() {
  local out
  out=$(aws ecs execute-command --cluster "$CLUSTER" --task "$TASK" \
    --container backend --interactive \
    --command "python -m app.scripts.create_user $1 '$2' --update" 2>&1)
  if grep -q "Created user" <<<"$out"; then
    echo "    created $1"
  elif grep -q "Updated password" <<<"$out"; then
    echo "    $1 already existed; password set"
  else
    echo "$out" >&2
    echo "creating $1 failed" >&2
    exit 1
  fi
}

echo "==> creating users"
create_user admin   "$(param ADMIN_PASSWORD)"
create_user svc-mcp "$(param ROSTER_SERVICE_PASSWORD)"
